<?php
require __DIR__.'/bootstrap.php'; require __DIR__.'/layout.php'; $u=require_login();
$opId=(int)($_GET['operacion']??$_POST['operacion_id']??0); $q=$db->prepare('SELECT o.*,c.nombre_completo,c.numero_documento,c.id cliente_id,r.id regla_id,r.descuento_maximo,r.monto_minimo,r.inicial_minima_porcentaje,r.cuotas_maximas,r.requiere_supervisor FROM operaciones o JOIN clientes c ON c.id=o.cliente_id LEFT JOIN campanas cp ON cp.cedente=o.cedente AND cp.cartera=o.cartera AND cp.activa=1 AND CURDATE() BETWEEN cp.fecha_inicio AND cp.fecha_fin LEFT JOIN reglas_negociacion r ON r.campana_id=cp.id AND r.tipo_acuerdo=COALESCE(?,r.tipo_acuerdo) AND r.activo=1 WHERE o.id=? LIMIT 1'); $q->execute([$_POST['tipo_acuerdo']??null,$opId]);$op=$q->fetch(); if(!$op){http_response_code(404);exit('Operación no encontrada');}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$tipo=in_array($_POST['tipo_acuerdo']??'', ['CANCELACION','CONVENIO'],true)?$_POST['tipo_acuerdo']:'';$monto=round((float)($_POST['monto_acordado']??0),2);$inicial=round((float)($_POST['monto_inicial']??0),2);$cuotas=(int)($_POST['numero_cuotas']??1);$saldo=(float)$op['saldo'];$descuento=$saldo>0?round((1-$monto/$saldo)*100,2):0;if(!$tipo||$monto<=0||$monto>$saldo||$cuotas<1||$cuotas>120||$inicial<0||$inicial>$monto)$error='Revisa los importes y el número de cuotas.';else{try{$db->beginTransaction();$outside=($op['descuento_maximo']!==null&&$descuento>(float)$op['descuento_maximo'])||($op['monto_minimo']!==null&&$monto<(float)$op['monto_minimo'])||($op['cuotas_maximas']!==null&&$cuotas>(int)$op['cuotas_maximas']);$estado=$outside?'PENDIENTE_APROBACION':'VIGENTE';$year=date('Y');$db->prepare('INSERT INTO secuencias_acuerdo(anio,ultimo) VALUES(?,LAST_INSERT_ID(1)) ON DUPLICATE KEY UPDATE ultimo=LAST_INSERT_ID(ultimo+1)')->execute([$year]);$seq=(int)$db->query('SELECT LAST_INSERT_ID()')->fetchColumn();$code=sprintf('BKC-%s-%06d',$year,$seq);$ins=$db->prepare('INSERT INTO acuerdos(codigo_acuerdo,cliente_id,operacion_id,tipo_acuerdo,saldo_negociado,porcentaje_descuento,monto_acordado,monto_inicial,numero_cuotas,fecha_acuerdo,estado,creado_por_id,creado_por) VALUES(?,?,?,?,?,?,?,?,?,CURDATE(),?,?,?)');$ins->execute([$code,$op['cliente_id'],$opId,$tipo,$saldo,$descuento,$monto,$inicial,$cuotas,$estado,$u['id'],$u['username']]);$id=(int)$db->lastInsertId();$remaining=$monto-$inicial;$base=floor(($remaining/$cuotas)*100)/100;$last=$remaining-$base*($cuotas-1);$date=new DateTimeImmutable($_POST['fecha_primera']??date('Y-m-d'));$ci=$db->prepare('INSERT INTO cuotas(acuerdo_id,numero_cuota,fecha_vencimiento,monto,estado) VALUES(?,?,?,?,?)');for($i=1;$i<=$cuotas;$i++){$amount=$i===$cuotas?$last:$base;$ci->execute([$id,$i,$date->format('Y-m-d'),$amount,'PENDIENTE']);$date=$date->modify('+1 month');}audit($db,$u['id'],$u['username'],'AGREEMENT_CREATED','ACUERDO',$id,null,['codigo'=>$code,'tipo'=>$tipo,'monto'=>$monto,'estado'=>$estado]);$db->commit();header('Location: '.url('acuerdos.php'));exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Agreement creation failed');$error='No se pudo guardar el acuerdo.';}}}
page_start('Generar acuerdo',$u);?><section class="panel"><h2><?=e($op['nombre_completo'])?></h2><p>Documento <?=e($op['numero_documento'])?> · Operación <?=e($op['numero_operacion'])?> · Saldo <?=money($op['saldo'])?></p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif?><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="operacion_id" value="<?=$opId?>"><label>Tipo de acuerdo<select name="tipo_acuerdo" required><option value="CANCELACION">Cancelación</option><option value="CONVENIO">Convenio</option></select></label><label>Monto acordado<input type="number" name="monto_acordado" min="0.01" max="<?=e($op['saldo'])?>" step="0.01" required></label><label>Inicial<input type="number" name="monto_inicial" min="0" step="0.01" value="0" required></label><label>Número de cuotas<input type="number" name="numero_cuotas" min="1" max="120" value="1" required></label><label>Primera cuota<input type="date" name="fecha_primera" value="<?=date('Y-m-d')?>" required></label><div class="rule"><b>Condiciones autorizadas</b><span>Descuento máximo: <?=e((string)($op['descuento_maximo']??'No configurado'))?>%</span><span>Cuotas máximas: <?=e((string)($op['cuotas_maximas']??'No configurado'))?></span></div><button class="primary" type="submit">Crear acuerdo</button></form></section><?php page_end();

